import { Key, useEffect, useState } from "react";

import { DocumentLookupResult, IComponent, StudioProApi } from "@mendix/extensions-api";

import { createDocumentEditorComponent } from "../utils/componentLoader";

import { createNewKnowledgebase, updateKnowledgebaseDocument } from "../../utils/knowledgebaseUtils";
import { handleProviderChange } from "./knowledgebaseHandlers";

import { mendixIconGreyBase64 } from "../../icons/modelIcons";
import { Knowledgebase, Provider } from "../../types/knowledgebase/knowledgebase";
import AppThemeProvider from "../components/AppThemeProvider";
import { CenteredLoadingSpinner } from "../components/CenteredLoadingSpinner";
import ComboBoxWithIcon from "../components/ComboBoxWithIcon";
import GroupBox from "../components/GroupBox";
import { ContentColumnSmall, PageContainer, PageContent } from "../components/PageContainers";
import MxCloudGenAI from "./providers/mxCloudGenAI";

const initialKnowledgebase: Knowledgebase = createNewKnowledgebase();

interface AppProps {
    studioPro: StudioProApi;
    documentId: string;
}

const App: React.FC<AppProps> = ({ studioPro, documentId }) => {
    const messageBoxApi = studioPro.ui.messageBoxes;
    const documentApi = studioPro.app.model.customBlobDocuments;
    const [documentVersion, setDocumentVersion] = useState(0);
    const [isLoaded, setIsLoaded] = useState(false);
    const [knowledgebase, setKnowledgebase] = useState(initialKnowledgebase);

    const providerOptions: { key: Provider; caption: string; icon?: string }[] = [
        { key: "MxCloudGenAI", caption: "Mendix Cloud GenAI", icon: mendixIconGreyBase64 },
    ];

    useEffect(() => {
        const handleDocumentsChanged = (event: { documents: Array<{ documentId: string }> }) => {
            const { documents } = event;
            if (documents.some((doc) => doc.documentId === documentId)) {
                setDocumentVersion((v) => v + 1);
            }
        };
        documentApi.addEventListener("documentsChanged", handleDocumentsChanged);
        return () => {
            documentApi.removeEventListener("documentsChanged", handleDocumentsChanged);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        documentApi
            .getDocumentById<Knowledgebase>(documentId)
            .then(async (documentFromModel: DocumentLookupResult<Knowledgebase>) => {
                if (documentFromModel && !("error" in documentFromModel)) {
                    const loadedKnowledgebase: Knowledgebase = documentFromModel.document.contents;
                    setKnowledgebase({ ...loadedKnowledgebase });
                    setIsLoaded(true);
                } else {
                    throw new Error(documentFromModel?.error || "Document not found");
                }
            })
            .catch(async (err) => {
                await messageBoxApi.show("error", "Error loading document", "Details: " + err?.message || err);
            });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [documentVersion]);

    const changeProvider = async (key: Key | null) => {
        handleProviderChange(
            knowledgebase,
            setKnowledgebase,
            updateKnowledgebaseDocument(studioPro, documentId),
            key as Provider
        )();
    };

    const validateProvider = () => {
        if (!knowledgebase.provider) {
            return "Model provider is required.";
        }
        return true;
    };

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainer>
                {!isLoaded && <CenteredLoadingSpinner />}
                {isLoaded && (
                    <PageContent>
                        <ContentColumnSmall>
                            <GroupBox label="Common">
                                <ComboBoxWithIcon
                                    ariaLabel="Provider"
                                    isDisabled={true}
                                    label="Provider"
                                    selectedKey={knowledgebase.provider}
                                    options={providerOptions}
                                    onSelectionChange={changeProvider}
                                    validate={validateProvider}
                                />
                            </GroupBox>
                            {knowledgebase.provider === "MxCloudGenAI" && (
                                <MxCloudGenAI
                                    studioPro={studioPro}
                                    knowledgebase={knowledgebase}
                                    setKnowledgebase={setKnowledgebase}
                                    updateStudioProDocument={updateKnowledgebaseDocument(studioPro, documentId)}
                                />
                            )}
                        </ContentColumnSmall>
                    </PageContent>
                )}
            </PageContainer>
        </AppThemeProvider>
    );
};

export const component: IComponent = createDocumentEditorComponent(App);
